/** Expo config plugin: release signing + versionCode for the Android build (plan 08, docs/release.md).
 *
 *  `android/` is gitignored and regenerated by `expo prebuild`, so the signing setup has to be
 *  injected at prebuild time. This plugin edits the generated `android/app/build.gradle`:
 *
 *  - adds a `release` signing config that reads the upload keystore from environment variables
 *    (`BOLID_KEYSTORE_PATH`, `BOLID_KEYSTORE_PASSWORD`, `BOLID_KEY_ALIAS`, `BOLID_KEY_PASSWORD`) when
 *    Gradle runs, and fails the build loudly if the path is set but the file or a password is missing;
 *  - makes the `release` build type use it only when `BOLID_KEYSTORE_PATH` is set. Without it (local
 *    development, a main-branch CI build with no secret) the release build stays debug-signed, so
 *    `npm run android:apk` keeps working;
 *  - when `BOLID_VERSION_CODE` is set at prebuild time (CI passes the run number), writes it as the
 *    Android `versionCode`.
 *
 *  No secret ever reaches the generated file: it only holds `System.getenv(...)` lookups.
 *  `scripts/check-signing-plugin.mjs` runs this against a fixture of the SDK's generated gradle file. */
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// bolid:release-signing (plugins/withReleaseSigning.js)';

const RELEASE_SIGNING_CONFIG = `signingConfigs {
        ${MARKER}
        if (System.getenv("BOLID_KEYSTORE_PATH")) {
            release {
                def ksFile = file(System.getenv("BOLID_KEYSTORE_PATH"))
                if (!ksFile.exists()) {
                    throw new GradleException("BOLID_KEYSTORE_PATH is set but no keystore exists at " + ksFile)
                }
                ["BOLID_KEYSTORE_PASSWORD", "BOLID_KEY_ALIAS", "BOLID_KEY_PASSWORD"].each { name ->
                    if (!System.getenv(name)) {
                        throw new GradleException(name + " must be set when BOLID_KEYSTORE_PATH is set")
                    }
                }
                storeFile ksFile
                storePassword System.getenv("BOLID_KEYSTORE_PASSWORD")
                keyAlias System.getenv("BOLID_KEY_ALIAS")
                keyPassword System.getenv("BOLID_KEY_PASSWORD")
            }
        }`;

const RELEASE_SIGNING_REF =
  'signingConfig System.getenv("BOLID_KEYSTORE_PATH") ? signingConfigs.release : signingConfigs.debug';

/** Parse `BOLID_VERSION_CODE`: unset or empty → null; otherwise a positive integer or a thrown error
 *  (a bad value must stop the build rather than ship versionCode 1). */
function parseVersionCode(raw) {
  if (raw === undefined || raw === null || String(raw).trim() === '') return null;
  const text = String(raw).trim();
  if (!/^\d+$/.test(text) || Number(text) < 1 || Number(text) > 2100000000) {
    throw new Error(
      `withReleaseSigning: BOLID_VERSION_CODE must be a whole number from 1 to 2100000000, got "${text}"`,
    );
  }
  return Number(text);
}

/** Pure transform of the generated `app/build.gradle` text. Idempotent. Throws when the Expo template
 *  no longer has the anchors it expects, so a template change fails prebuild instead of silently
 *  shipping a debug-signed release. */
function applyReleaseSigning(contents, env = process.env) {
  let g = contents;

  if (!g.includes(MARKER)) {
    if (!/signingConfigs \{/.test(g)) {
      throw new Error('withReleaseSigning: no `signingConfigs {` block in app/build.gradle');
    }
    g = g.replace(/signingConfigs \{/, RELEASE_SIGNING_CONFIG);

    const buildTypes = g.indexOf('buildTypes {');
    if (buildTypes < 0) {
      throw new Error('withReleaseSigning: no `buildTypes {` block in app/build.gradle');
    }
    const releaseMatch = /\brelease\s*\{/.exec(g.slice(buildTypes));
    if (!releaseMatch) {
      throw new Error('withReleaseSigning: no `release {` build type in app/build.gradle');
    }
    const releaseStart = buildTypes + releaseMatch.index + releaseMatch[0].length;
    const debugRef = 'signingConfig signingConfigs.debug';
    const refAt = g.indexOf(debugRef, releaseStart);
    // The reference must sit directly inside the release block (no nested or closed block between).
    if (refAt < 0 || /[{}]/.test(g.slice(releaseStart, refAt))) {
      throw new Error(
        'withReleaseSigning: the release build type no longer uses `signingConfig signingConfigs.debug`',
      );
    }
    g = g.slice(0, refAt) + RELEASE_SIGNING_REF + g.slice(refAt + debugRef.length);
  }

  const versionCode = parseVersionCode(env.BOLID_VERSION_CODE);
  if (versionCode !== null) {
    if (!/versionCode \d+/.test(g)) {
      throw new Error('withReleaseSigning: no `versionCode` line in app/build.gradle');
    }
    g = g.replace(/versionCode \d+/, `versionCode ${versionCode}`);
  }
  return g;
}

function withReleaseSigning(config) {
  // Also set it on the config, so Expo's own versionCode step agrees whatever order mods run in.
  const versionCode = parseVersionCode(process.env.BOLID_VERSION_CODE);
  if (versionCode !== null) {
    config.android = { ...(config.android ?? {}), versionCode };
  }
  return withAppBuildGradle(config, (c) => {
    if (c.modResults.language !== 'groovy') {
      throw new Error('withReleaseSigning: only a Groovy app/build.gradle is supported');
    }
    c.modResults.contents = applyReleaseSigning(c.modResults.contents, process.env);
    return c;
  });
}

module.exports = withReleaseSigning;
module.exports.applyReleaseSigning = applyReleaseSigning;
module.exports.parseVersionCode = parseVersionCode;
module.exports.RELEASE_SIGNING_MARKER = MARKER;
